def pair_with_sum(nums, target):        # nums sorted ascending
    lo, hi = 0, len(nums) - 1
    while lo < hi:
        total = nums[lo] + nums[hi]
        if total == target:
            return [lo, hi]
        if total < target:
            lo += 1      # nums[lo] too small for every partner left
        else:
            hi -= 1      # nums[hi] too big for every partner left
    return []

def count_pairs_below(nums, target):    # pairs i < j, sum < target
    lo, hi, count = 0, len(nums) - 1, 0
    while lo < hi:
        if nums[lo] + nums[hi] < target:
            count += hi - lo     # nums[lo] works with all of (lo, hi]
            lo += 1
        else:
            hi -= 1
    return count

print(pair_with_sum([1, 3, 4, 6, 8, 11], 10))   # [2, 3]
print(count_pairs_below([1, 2, 3, 4, 5], 6))    # 4

