def three_sum(nums):
    nums.sort()
    result, n = [], len(nums)
    for i in range(n - 2):
        if nums[i] > 0:
            break                        # all remaining values are positive
        if i > 0 and nums[i] == nums[i - 1]:
            continue                     # same first value as last time
        lo, hi = i + 1, n - 1
        while lo < hi:
            total = nums[i] + nums[lo] + nums[hi]
            if total < 0:
                lo += 1
            elif total > 0:
                hi -= 1
            else:
                result.append([nums[i], nums[lo], nums[hi]])
                lo += 1
                hi -= 1
                while lo < hi and nums[lo] == nums[lo - 1]:
                    lo += 1              # skip repeats of the value just used
    return result

print(three_sum([-1, 0, 1, 2, -1, -4]))   # [[-1, -1, 2], [-1, 0, 1]]
print(three_sum([0, 0, 0, 0]))            # [[0, 0, 0]]

