def max_area(height):
    lo, hi = 0, len(height) - 1
    best = 0
    while lo < hi:
        best = max(best, min(height[lo], height[hi]) * (hi - lo))
        if height[lo] > height[hi]:
            lo += 1
        else:
            hi -= 1
    return best

def all_pairs(nums, target):
    lo, hi = 0, len(nums) - 1
    pairs = []
    while lo < hi:
        total = nums[lo] + nums[hi]
        if total == target:
            pairs.append((nums[lo], nums[hi]))
        elif total < target:
            lo += 1
        else:
            hi -= 1
    return pairs
